<title>Glimpse of pathogenesis</title>
<script type="text/javascript" id="MathJax-script" async
  src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js">
</script>
<style>
  body {
    font-family: "Times New Roman", Times, serif;
    margin: 0;
    padding: 20px 30px;
    position: relative;
  }
  .header {
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    height: 110px;
    margin-bottom: 10px;
  }
  .logo {
    width: 90px;
    height: 90px;
    position: absolute;
  }
  .logo-left {
    left: 0;
    top: 0;
  }
  .logo-right {
    right: 0;
    top: 0;
  }
  .logo img {
    width: 100%;
    height: 100%;
  }
  .placeholder {
    border: 1px solid #999;
    background: #f5f5f5;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    font-size: 11px;
    color: #555;
    box-sizing: border-box;
  }
  .title {
    color: #cc0000;
    font-size: 32px;
    font-weight: bold;
    text-align: center;
    font-style: italic;
    font-family: "Times New Roman", Times, serif;
  }
