    font-weight: bold;
    padding: 6px 8px;
    border-bottom: 2px solid #990000;
    border-top: 1px solid #990000;
    font-style: italic;
    font-size: 12.5px;
  }
  table.data-table td {
    vertical-align: top;
    padding: 5px 8px;
    border: none;
  }
  table.data-table tr:not(:last-child) td {
    border-bottom: 1px solid #cfd9a8;
  }
  .pathotype {
    font-weight: bold;
    font-style: italic;
    white-space: nowrap;
  }
  .footer-citation {
    text-align: right;
    font-weight: bold;
    font-style: italic;
    margin-top: 25px;
    font-size: 16px;
  }
</style>
</head>
<body>

  <div class="header">
    <div class="logo logo-left">
      <div class="placeholder" style="width:90px;height:90px; border-radius:50%;">[Logo: ICAR emblem]</div>
    </div>
    <div class="title">Glimpse of pathogenesis</div>
    <div class="logo logo-right">
      <div class="placeholder" style="width:90px;height:90px; border-radius:50%;">[Logo: IVRI seal]</div>
    </div>
  </div>

  <table class="data-table">
    <thead>
      <tr>
        <th>Pathotype</th>
        <th>Host(s)</th>
        <th>Site</th>
        <th>Disease(S)</th>
        <th>Resevoir(S)/sources</th>
        <th>Rx</th>
        <th>Adhesion</th>
        <th>Genetic Identifiers</th>
      </tr>
    </thead>
    <tbody>
      <tr>
        <td class="pathotype">tEPEC<br>aEPEC</td>
        <td>Children &lt;5 yr, adults at high<br>inocula</td>
        <td>Small intestine</td>
        <td>Profuse watery diarrhea</td>
        <td>Humans<br>Humans, animals</td>
        <td>Oral rehydration, antibiotics<br>for persistent cases</td>
        <td>Attaching and effacing</td>
        <td><em>eae&#8314;, bfp&#8314;, stx&#8315;</em><br><em>eae&#8314;, stx&#8315;</em></td>
      </tr>
      <tr>
        <td class="pathotype">STEC</td>
        <td>Adults, children</td>
        <td>Distal ileum, colon</td>
        <td>Watery diarrhea, hemorrhagic<br>colitis, HUS</td>
        <td>Humans, animals,<br>food, water</td>
        <td>Hydration, supportive for<br>HUS</td>
        <td>Attaching and effacing<sup>b</sup></td>
        <td><em>eae&#8314;/&#8315;, stx&#8314;</em></td>
      </tr>
      <tr>
        <td class="pathotype">EIEC/<em>Shigella</em></td>
        <td>Children &lt;5 yr, adults, travelers,<br>immunocompromised<br>persons</td>
        <td>Colon</td>
        <td>Shigellosis/bacillary dysentery,<br>potential HUS</td>
        <td>Humans, animals,<br>food, water</td>
        <td>Oral rehydration, antibiotics</td>
        <td>NA (invasive)</td>
        <td><em>ipaH&#8314;, ial&#8314;, stx&#8314;</em> (S.<br><em>dysenteriae</em>)</td>
      </tr>
      <tr>
        <td class="pathotype">EAEC</td>
        <td>Adults<br><br>Children</td>
        <td>Small intestine and/or<br>colon</td>
        <td>Traveler's diarrhea, HUS<br>(<em>sx</em>&#8314;)<br>Persistent diarrhea</td>
        <td>Food, occasionally<br>adult carriers</td>
        <td>Antibiotics, oral rehydration<br><br>Antibiotics, oral<br>rehydration, potentially<br>probiotics</td>
        <td>Stacked brick and/or<br>invasive</td>
        <td><em>aatA&#8314;, aaiC&#8314;</em><br>other candidates</td>
      </tr>
      <tr>
        <td class="pathotype">ETEC</td>
        <td>Immunocompromised persons<br>Children &lt;5 yr, travelers</td>
        <td>Small intestine</td>
        <td>Persistent diarrhea<br>Watery diarrhea</td>
        <td>Food, water, humans,<br>animals</td>
        <td>Fluoroquinolones<br>Rehydration, antibiotics</td>
        <td>CF mediated</td>
        <td>CFs, LT, ST</td>
      </tr>
      <tr>
        <td class="pathotype">DAEC</td>
        <td>Children (increasing in severity<br>from 18 mo to 5 yr), adults</td>
        <td>Intestine (uncharacterized<br>location)</td>
        <td>Persistent watery diarrhea in<br>children, speculated to<br>contribute to Crohn's<br>disease in adults</td>
        <td>Unknown</td>
        <td>Rehydration</td>
        <td>Diffuse adherent and/or<br>invasive</td>
        <td>No uniform markers</td>
      </tr>
      <tr>
        <td class="pathotype">AIEC</td>
        <td>Adults, children</td>
        <td>Small intestine</td>
        <td>Crohn's disease</td>
        <td>Unknown</td>
        <td>Antibiotics, surgical<br>resection</td>
        <td>NA (invasive)</td>
        <td>Uncharacterized</td>
      </tr>
    </tbody>
  </table>

  <div class="footer-citation">(Croxen et. al., 2013)</div>

</body>
